export const RR_APP_CSS = "html,\nbody {\n  background: #fff;\n}\n\n@media (prefers-color-scheme: dark) {\n  html,\n  body {\n    background: #030712;\n    color-scheme: dark;\n  }\n}\n\nbody {\n  margin: 0;\n  font-family: \"Inter\", ui-sans-serif, system-ui, sans-serif, \"Apple Color Emoji\", \"Segoe UI Emoji\", \"Segoe UI Symbol\",\n    \"Noto Color Emoji\";\n}\n\n/* The starter's Tailwind utilities, written out. */\n.welcome {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding-top: 4rem;\n  padding-bottom: 1rem;\n}\n\n.welcome-body {\n  flex: 1 1 0%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 4rem;\n  min-height: 0;\n}\n\n.welcome-header {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 2.25rem;\n}\n\n.welcome-logo {\n  width: 500px;\n  max-width: 100vw;\n  padding: 1rem;\n  box-sizing: border-box;\n}\n\n.welcome-logo-light,\n.welcome-logo-dark {\n  width: 100%;\n}\n\n.welcome-logo-light {\n  display: block;\n}\n\n.welcome-logo-dark {\n  display: none;\n}\n\n.welcome-nav-wrap {\n  max-width: 300px;\n  width: 100%;\n  padding: 0 1rem;\n  box-sizing: border-box;\n}\n\n.welcome-nav {\n  border: 1px solid #e5e7eb;\n  border-radius: 1.5rem;\n  padding: 1.5rem;\n}\n\n.welcome-nav ul {\n  margin: 1rem 0 0;\n  padding: 0;\n  list-style: none;\n}\n\n.welcome-nav-title {\n  margin: 0;\n  line-height: 1.5rem;\n  color: #374151;\n  text-align: center;\n}\n\n.welcome-link {\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n  align-self: stretch;\n  padding: 0.75rem;\n  line-height: 1.5;\n  color: #1d4ed8;\n  text-decoration: none;\n}\n\n.welcome-link:hover {\n  text-decoration: underline;\n}\n\n.welcome-icon {\n  stroke: #4b5563;\n}\n\n.welcome-link:hover .welcome-icon {\n  stroke: currentColor;\n}\n\n@media (prefers-color-scheme: dark) {\n  .welcome-logo-light {\n    display: none;\n  }\n\n  .welcome-logo-dark {\n    display: block;\n  }\n\n  .welcome-nav {\n    border-color: #374151;\n  }\n\n  .welcome-nav-title {\n    color: #e5e7eb;\n  }\n\n  .welcome-link {\n    color: #3b82f6;\n  }\n\n  .welcome-icon {\n    stroke: #d1d5db;\n  }\n}\n\n.error-page {\n  padding: 4rem 1rem 1rem;\n  max-width: 1280px;\n  margin: 0 auto;\n}\n\n.error-stack {\n  width: 100%;\n  padding: 1rem;\n  overflow-x: auto;\n  box-sizing: border-box;\n}\n";

